<template><view class="page"><view class="tabs"><text :class="tab==='models'?'active':''" @click="tab='models'">模型版本</text><text :class="tab==='rules'?'active':''" @click="tab='rules'">检测规则</text><text :class="tab==='effects'?'active':''" @click="tab='effects'">效果统计</text></view><view v-if="loading" class="state">正在加载…</view><view v-else class="list"><template v-if="tab==='models'"><view v-for="item in models" :key="item.id" class="card"><view class="top"><text class="title">{{item.name}} {{item.version}}</text><text class="badge" :class="item.status==='ACTIVE'?'active-badge':''">{{item.status==='ACTIVE'?'当前使用':'未启用'}}</text></view><text class="meta">能力：{{types(item.capabilities)}}\n服务：{{item.serviceEndpoint||'-'}}</text></view></template><template v-else-if="tab==='rules'"><view v-for="item in rules" :key="item.id" class="card"><view class="top"><text class="title">{{item.name}}</text><text class="badge">{{item.enabled?'已启用':'已停用'}}</text></view><text class="meta">类型：{{typeName(item.detectionType)}}\n阈值：{{Math.round(item.confidenceThreshold*100)}}%\n检测区域：{{item.regionPoints?'已配置':'全画面'}}</text></view></template><template v-else><view v-for="item in effects" :key="item.detectionType" class="card"><view class="top"><text class="title">{{typeName(item.detectionType)}}</text><text class="rate">{{Math.round(item.confirmationRate*100)}}%</text></view><view class="bar"><view :style="{width:Math.round(item.confirmationRate*100)+'%'}"/></view><text class="meta">检测 {{item.totalCount}} 次 · 确认 {{item.confirmedCount}} 次 · 误报 {{item.falsePositiveCount}} 次</text></view></template><EmptyState v-if="!currentCount" title="暂无数据"/></view></view></template>
<script setup lang="ts">
import{computed,ref,watch}from'vue';import{onShow}from'@dcloudio/uni-app';import EmptyState from'@/components/EmptyState.vue';import{queryAiModels,queryAiRules,queryDetectionEffects,type AiModel,type AiRule,type DetectionEffect}from'@/api/inspection';import{showRequestError}from'@/utils/request';import{useAuthStore}from'@/stores/auth';const auth=useAuthStore(),tab=ref<'models'|'rules'|'effects'>('models'),models=ref<AiModel[]>([]),rules=ref<AiRule[]>([]),effects=ref<DetectionEffect[]>([]),loading=ref(false);const currentCount=computed(()=>tab.value==='models'?models.value.length:tab.value==='rules'?rules.value.length:effects.value.length);async function load(){loading.value=true;try{if(tab.value==='models')models.value=await queryAiModels();else if(tab.value==='rules')rules.value=await queryAiRules();else effects.value=await queryDetectionEffects()}catch(e){showRequestError(e)}finally{loading.value=false}}function typeName(v:string){return({PERSON:'人员检测',VEHICLE:'车辆检测',INTRUSION:'区域入侵',CROSS_LINE:'越界检测',FIRE_SMOKE:'烟火检测',HELMET:'安全帽检测',BLACK_SCREEN:'黑屏检测',FREEZE:'冻结检测',BLUR:'模糊检测',OCCLUSION:'遮挡检测'}as Record<string,string>)[v]||v}function types(v:string){return v.split(',').map(typeName).join('、')}watch(tab,load);onShow(()=>{if(auth.requireAuth())load()})
</script><style scoped>.page{min-height:100vh}.tabs{display:flex;justify-content:space-around;padding:24rpx;background:#fff;color:#8992a6;font-size:26rpx}.tabs .active{color:#2368f2;font-weight:600}.list{padding:22rpx}.card{margin-bottom:18rpx;padding:28rpx;background:#fff;border-radius:22rpx}.top{display:flex;align-items:center;justify-content:space-between;gap:16rpx}.title{font-size:28rpx;font-weight:600}.badge{padding:7rpx 13rpx;color:#667085;background:#edf0f5;border-radius:999rpx;font-size:20rpx}.active-badge{color:#14804a;background:#e4f7ed}.meta{display:block;margin-top:15rpx;color:#7b8498;font-size:23rpx;line-height:1.65}.rate{color:#2368f2;font-size:30rpx;font-weight:700}.bar{height:14rpx;margin-top:20rpx;background:#edf0f5;border-radius:999rpx;overflow:hidden}.bar view{height:100%;background:#2368f2}.state{padding:100rpx;text-align:center;color:#8992a6}</style>
